            close(fd);
            return false;
        }
        if (st.st_size < 2*sizeof(int64_t)) {
            close(fd);
            return false;
        }

        int64_t* mapped_ptr = (int64_t*)mmap(
            NULL, 2*sizeof(int64_t), PROT_READ, MAP_SHARED, fd, 0
