```

Reading two `int64_t` values from shared memory without any synchronization can produce torn reads on 32-bit platforms and/or inconsistent pairs (e.g., `update_time` from one write and `input_time` from another). Consider using a simple sequence-lock layout in shared memory (seq, update_time, input_time, seq) and retry until the sequence is stable, or store values as atomics in a properly defined shared struct (with clear alignment requirements) and read with acquire semantics.
```suggestion
    static int fd = -1;
    static int64_t* seg_ptr = NULL;
    if (!seg_ptr) {
        fd = shm_open("/idle_detect_shmem",  O_RDONLY, 0);
        if (fd < 0) return false;
        seg_ptr = (int64_t*)mmap(
            NULL, 2*sizeof(int64_t), PROT_READ, MAP_SHARED, fd, 0
        );
        if (seg_ptr == (int64_t*)MAP_FAILED) {
            seg_ptr = NULL;
            return false;
        }
    }
    if (!seg_ptr || fd < 0) return false;

    struct stat st;
    if (fstat(fd, &st)) return false;
    if (st.st_size < 2*sizeof(int64_t)) return false;

    // Read a stable snapshot from shared memory.
    // Re-read update_time around input_time and retry if it changed,
    // so we don't accept a mixed pair from concurrent writer updates.
    //
    for (int i = 0; i < 8; ++i) {
        int64_t update_time_1 = seg_ptr[0];
        int64_t input_time = seg_ptr[1];
        int64_t update_time_2 = seg_ptr[0];

        if (update_time_1 != update_time_2) continue;
        if (update_time_1 > gstate.now+10) return false;
        if (update_time_1 < gstate.now-60) return false;

        idle_time = gstate.now - input_time;
        //printf("idle time: %ld\n", idle_time);
        return true;
    }
    return false;
```

