    if ($tag_pos === false) {
        return null;
    }
    if (strstr($tag, "/>")) {
        $cursor = $tag_pos + strlen($tag);
        return $tag;
    }
    $content_start = $tag_pos + strlen($tag);
    $close_pos = strpos($xml, $closetag, $content_start);
    if ($close_pos === false) {
        return null;
